add_action( 'admin_init', 'perfectpixel_modified_column_setup' );

function perfectpixel_modified_column_setup() {
	foreach ( get_post_types( array( 'show_ui' => true ) ) as $type ) {
		if ( in_array( $type, array( 'attachment', 'shop_order' ), true ) ) {
			continue;
		}
		add_filter( "manage_{$type}_posts_columns", 'perfectpixel_modified_column' );
		add_action( "manage_{$type}_posts_custom_column", 'perfectpixel_modified_column_value', 10, 2 );
		add_filter( "manage_edit-{$type}_sortable_columns", 'perfectpixel_modified_column_sortable' );
	}
}

function perfectpixel_modified_column( $columns ) {
	$columns['perfectpixel_modified'] = 'Τελευταία τροποποίηση';
	return $columns;
}

function perfectpixel_modified_column_value( $column, $post_id ) {
	if ( 'perfectpixel_modified' !== $column ) {
		return;
	}
	echo esc_html( get_the_modified_date( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), $post_id ) );
	$editor_id = get_post_meta( $post_id, '_edit_last', true );
	$editor    = $editor_id ? get_userdata( $editor_id ) : null;
	if ( $editor ) {
		echo '<br><small>' . esc_html( $editor->display_name ) . '</small>';
	}
}

function perfectpixel_modified_column_sortable( $columns ) {
	$columns['perfectpixel_modified'] = 'modified';
	return $columns;
}
